# Plots time series from ROS signals
# Author: Wail Gueaieb

import matplotlib.pyplot as plt

class PyPlotter():
    def __init__(self, rows=1, fig_title='', ylabels=[]):
        self.rows = rows
        self.ylabels = [] 
        for i in range(self.rows):
            if i < len(ylabels):
                self.ylabels.append(ylabels[i])
            else:
                self.ylabels.append('')

        # set up dynamic plotting (non-blocking)
        plt.ion()
        self.time_data = []
        self.start_time = None
        self.value_data = [[] for _ in range(self.rows)] # empty array of "rows" empty arrays of value data
        self.fig, self.ax = plt.subplots(self.rows, 1, figsize=(10,8))
        self.fig.suptitle(fig_title)

    def compute_time(self, current_time):
        if self.start_time is None:
            self.start_time = current_time
        return (current_time - self.start_time)

    def update_figure(self, current_time, new_value, pause_period=0.001):
        self.time_data.append(self.compute_time(current_time))

        if self.rows == 1:
            self.value_data[0].append(new_value[0])
            # clear axis and re-plot the updated data
            self.ax.clear()
            self.ax.plot(self.time_data , self.value_data[0], label=self.ylabels[0])
            self.ax.set_ylabel(self.ylabels[0])
            self.ax.legend()
            self.ax.set_xlabel('Time (s)')
        else:
            for i in range(self.rows):
                self.value_data[i].append(new_value[i])
                # clear each axis and re-plot the updated data
                self.ax[i].clear()
                self.ax[i].plot(self.time_data , self.value_data[i], label=self.ylabels[i])
                self.ax[i].set_ylabel(self.ylabels[i])
                self.ax[i].legend()
            self.ax[self.rows-1].set_xlabel('Time (s)')

        self.fig.tight_layout(rect=[0, 0.03, 1, 0.95])
        plt.draw()
        # short pause to allow the GUI event loop to update
        plt.pause(pause_period)

